     * - statuses 400, 403 (codes not bound in the contract)
     *
     * @return `ContactRevealResponse` (200)
     *
     * @param body Ask for a seller's numbers.
     */
    public suspend fun revealContacts(body: ContactRevealRequest): StapelResult<ContactRevealResponse, RevealContactsError>

    /**
     * Unblock user
     *
     * Unblock a user. Sets relationship to "neutral" status.
     *
     * Wire: `POST /profiles/api/v1/{user_id}/unblock`   `unblock_user`
     *
     * Permissions: IsNotAnonymousUser
     *
     * Auth: required
     *
     * Errors: statuses 401 (codes not bound in the contract).
     *
     * Example response (RelationshipActionResponse):
     * ```json
     * {
     *     "status": "following",
     *     "success": true
     * }
     * ```
     *
     * @return `RelationshipActionResponse` (200)
     *
     * @param userId User UUID to unblock
     */
    public suspend fun unblockUser(userId: String): StapelResult<RelationshipActionResponse, UnblockUserError>

    /**
     * Unfollow user
     *
     * Unfollow a user. Sets relationship to "neutral" status.
     *
     * Wire: `POST /profiles/api/v1/{user_id}/unfollow`   `unfollow_user`
     *
     * Permissions: IsNotAnonymousUser
     *
     * Auth: required
     *
     * Errors: statuses 401 (codes not bound in the contract).
     *
     * Example response (RelationshipActionResponse):
     * ```json
     * {
     *     "status": "following",
     *     "success": true
     * }
     * ```
     *
     * @return `RelationshipActionResponse` (200)
     *
     * @param userId User UUID to unfollow
     */
    public suspend fun unfollowUser(userId: String): StapelResult<RelationshipActionResponse, UnfollowUserError>

    /**
     * Unsubscribe from notifications
     *
     * Verify HMAC token and toggle the corresponding notification preference off. Uses POST per RFC 8058 (List-Unsubscribe-Post).
     *
     * Wire: `POST /profiles/api/v1/notifications/unsubscribe`   `unsubscribe_notifications`
     *
     * Permissions: AllowAny
     *
     * Auth: optional
     *
     * Errors: statuses 400 (codes not bound in the contract).
     *
     * @return `JsonObject` (200)
     */
    public suspend fun unsubscribeNotifications(token: String): StapelResult<JsonObject, UnsubscribeNotificationsError>

    /**
     * Update a contact
     *
     * Change the label, the policy or the on/off switch (PATCH semantics). The number itself is not editable — a different number is a different thing to prove — and nothing here touches `verified_at`. Somebody else's contact answers 404.
     *
     * Wire: `PATCH /profiles/api/v1/contacts/{contact_id}`   `update_my_contact`
     *
     * Permissions: IsNotAnonymousUser
     *
     * Auth: required
     *
     * Errors (bound by contract):
     * - `ContactsInvalidPolicy` (400) — Unknown visibility policy. Allowed here: {policies}
     * - `ContactNotFound` (404) — Contact not found
     * - statuses 403 (codes not bound in the contract)
     *
     * Example response (ContactResponse):
     * ```json
     * {
     *     "created_at": "2026-09-11T08:00:00Z",
     *     "enabled": true,
     *     "id": 7,
     *     "kind": "phone",
     *     "label": "Work",
     *     "policy": "members",
     *     "reveal_count": 12,
     *     "value": "+15550100",
     *     "verified": true,
     *     "verified_at": "2026-09-11T09:00:00Z"
     * }
     * ```
     *
     * @return `ContactResponse` (200)
     *
     * @param contactId Contact id
     * @param body Change a contact (PATCH, all optional).
     *
     * The number itself is not editable: a different number is a different
     * thing to prove, so it is a different contact. Everything else the owner
     * may change at will, and none of it touches `verified_at`.
     */
    public suspend fun updateMyContact(contactId: Int, body: PatchedContactUpdateRequest? = null): StapelResult<ContactResponse, UpdateMyContactError>

    /**
     * Update my profile
     *
     * Update current user's profile. All fields are optional (PATCH semantics).
     *
     * Wire: `PATCH /profiles/api/v1/me`   `update_my_profile`
     *
     * Permissions: IsAuthenticated
     *
     * Auth: required
     *
     * Errors (bound by contract):
     * - `AvatarGravatarHash` (400) — Gravatar avatar must be an email hash (32 or 64 hex characters)
     * - `AvatarNotFound` (400) — Avatar not found on CDN
     * - `AvatarSourceMismatch` (400) — Avatar reference is a CDN reference but avatar_source says otherwise — send avatar_source="cdn" with it, or omit avatar_source and it will be derived from the reference
     * - `AvatarUrlHost` (400) — Avatar URL host is not allowed here
     * - `AvatarUrlScheme` (400) — Avatar URL must use one of: {schemes}
     * - `InvalidAvatarFormat` (400) — Invalid avatar reference format. Expected: avatar/<hash>
     * - statuses 401 (codes not bound in the contract)
     *
     * Example response (ProfileResponse):
     * ```json
     * {
     *     "app_language": {
     *         "code": "en",
     *         "flag": "/flags/en.svg",
     *         "name": "English"
     *     },
     *     "auto_detected_language": "de",
     *     "auto_translate_content": false,
     *     "avatar": "avatar/abc123",
     *     "avatar_image": null,
     *     "avatar_source": "file",
     *     "created_at": "2025-01-15T12:00:00Z",
     *     "display_name": "Ada Lovelace",
     *     "email_messages": true,
     *     "email_system": true,
     *     "essential_cookies_accepted": true,
     *     "followers_count": 42,
     *     "following_count": 15,
     *     "initial_setup_passed": true,
     *     "location_display_name_broad": "LU - Differdange",
     * …
     * ```
     *
     * @return `ProfileResponse` (200)
     *
     * @param body Update profile fields (PATCH, all optional).
     */
    public suspend fun updateMyProfile(body: PatchedProfileUpdateRequest? = null): StapelResult<ProfileResponse, UpdateMyProfileError>
}
